// SPECIAL PER-LEVEL: ricostruito direttamente da thewest_items_completo.json.
// Vengono importati solo i bonus XP, Soldi, Fortuna, Rigenerazione, Drop e Velocità
// realmente marcati nel sorgente come type="character", key="level".
// Un bonus normale (es. Aponi +5% XP) resta fisso.
const SPECIAL_PER_LEVEL = {};
for(const item of EMBEDDED_ITEMS){
  const spec=SPECIAL_PER_LEVEL[String(item.id)];
  if(!spec) continue;
  item.per_level=item.per_level||{};
  for(const [k,info] of Object.entries(spec)){
    if(typeof item[k]!=="number") item[k]=info.value;
    item.per_level[k]={roundingMethod:info.roundingMethod||"ceil"};
  }
}

// V36: normalizzazione GENERALE dei bonus speciali fissi direttamente da bonus_desc.
// Questi bonus NON dipendono dal livello del personaggio: il livello viene usato
// solo per le voci esplicitamente marcate "per Livello". In questo modo non
// perdiamo bonus come Punti lavoro, Esperienza, Soldi, Fortuna e Probabilità.
function normalizeFixedSpecialBonuses(item){
  if(!Array.isArray(item.bonus_desc)) return;
  for(const rawDesc of item.bonus_desc){
    const desc=String(rawDesc||'');
    // Ignora esplicitamente i bonus per livello: sono già gestiti da per_level.
    if(/\(\s*per\s*livello\s*\)/i.test(desc)) continue;
    const numMatch=desc.match(/[+-]?\d+(?:[.,]\d+)?/);
    if(!numMatch) continue;
    const num=Number(numMatch[0].replace(',','.'));
    if(!Number.isFinite(num)) continue;
    const pct=/\d+(?:[.,]\d+)?%/.test(desc);
    if(/punti\s+lavoro/i.test(desc)){
      item.labor_pts=num;
      continue;
    }
    if(/esperienza/i.test(desc)){
      item.xp=pct ? num/100 : num;
      continue;
    }
    if(/soldi|salario/i.test(desc)){
      item.money=pct ? num/100 : num;
      continue;
    }
    if(/maggior\s+fortuna|fortuna/i.test(desc)){
      item.luck=pct ? num/100 : num;
      continue;
    }
    if(/rigenerazione/i.test(desc)){
      item.regen=pct ? num/100 : num;
      continue;
    }
    if(/probabilit(?:à|a)\s+di\s+trovare\s+prodotti/i.test(desc)){
      item.drop=pct ? num/100 : num;
      continue;
    }
    if(/velocit(?:à|a)/i.test(desc)){
      item.spd=pct ? num/100 : num;
      if(item.hspd==null) item.hspd=num;
    }
  }
}
for(const item of EMBEDDED_ITEMS) normalizeFixedSpecialBonuses(item);


