for(const item of EMBEDDED_ITEMS){
  const rows=FIXED_SPECIAL_BY_ID[String(item.id)]||[];
  for(const b of rows){
    const v=Number(b.value); if(!Number.isFinite(v)) continue;
    if(b.type==='experience') item.xp=v;
    else if(b.type==='dollar') item.money=v;
    else if(b.type==='luck') item.luck=v;
    else if(b.type==='drop') item.drop=v;
    else if(b.type==='regen') item.regen=v;
    else if(b.type==='speed'){ item.spd=v; if(item.hspd==null) item.hspd=v*100; }
    else if(b.type==='pray') item.pra=v;
    else if(b.type==='job'){
      if(String(b.job)==='all'){ item.labor_pts=v; }
      else {
        const jid=Number(b.job);
        if(Number.isFinite(jid)){
          const key=`lbr_${jid}`; item[key]=v;
          item._job_bonus_desc=item._job_bonus_desc||[];
          item._job_bonus_desc.push([jid,String(b.desc||'')]);
        }
      }
    }
  }
}

// V35: bonus Punti Lavoro verso un lavoro specifico.
// Il database ItemManager li espone come bonus di tipo "job" con job=<ID> e value.
// Nel popup originale queste voci sono rappresentate come lbr_<jobId>;
// per i bonus "tutti i lavori" continuiamo a usare labor_pts.
const JOB_BONUSES = {};
for(const item of EMBEDDED_ITEMS){
  const jb=JOB_BONUSES[String(item.id)];
  if(!jb) continue;
  if(jb.job==='all'){
    if(item.labor_pts==null) item.labor_pts=Number(jb.value)||0;
    continue;
  }
  const jid=Number(jb.job);
  if(!Number.isFinite(jid)) continue;
  const key=`lbr_${jid}`;
  item[key]=Number(jb.value)||0;
  item._job_bonus_desc=item._job_bonus_desc||[];
  item._job_bonus_desc.push([jid,String(jb.desc||'')]);
}

// Normalizza il bonus velocità: in alcuni record è presente solo in bonus_desc (es. "+100% velocità").
for(const item of EMBEDDED_ITEMS){
  if(item.hspd==null && Array.isArray(item.bonus_desc)){
    for(const desc of item.bonus_desc){
      const m=String(desc).match(/([+-]?\d+(?:[.,]\d+)?)%\s*velocità/i);
      if(m){
        const speed=Number(m[1].replace(',', '.'));
        item.hspd=speed;
        if(item.spd==null) item.spd=speed;
        break;
      }
    }
  }
}

let items=[],activeItem=null,timer=null,lastEvent=null;
const upgradeById=new Map();

// V26: queste costanti devono essere inizializzate prima della prima render()
// chiamata da init(), altrimenti il TDZ di const interrompe il rendering dei pantaloni.
const compareSelected=new Set();
const MAX_COMPARE=4;
const $=s=>document.querySelector(s);
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c]));
const fmt=v=>Number.isInteger(v)?String(v):String(Number(v.toFixed(3))).replace(".",",");
function imageUrl(i){return i.image||""}
function characterLevel(){
  const n=Number($("#level").value);
  return Number.isFinite(n)?Math.max(0,Math.floor(n)):0;
}
function selectedUpgrade(item){
  if(!item || item.upg!==1) return 0;
  const n=Number(upgradeById.get(String(item.id)) ?? 0);
  return Number.isFinite(n)?Math.min(5,Math.max(0,Math.floor(n))):0;
}
function perLevelInfo(item,k){
  const map=item.per_level;
  if(!map) return null;
  if(map[k]) return map[k];
  const aliases={
    str:"strength", mob:"flexibility", dex:"dexterity", cha:"charisma",
    sta:"endurance", tou:"tough", hea:"health", punch:"punch",
    ref:"reflex", dod:"dodge", fin:"finger_dexterity", hid:"hide",
    aim:"aim", pit:"pitfall", rid:"ride", ani:"animal", lea:"leadership",
    tra:"trade", rep:"repair", tac:"tactic", app:"appearance", swi:"swim",
    con:"build", sho:"shot", fir:"firearms", her:"herbalism",
    exp:"experience", con:"build", dmg:"damage"
  };
  const key=aliases[k]||k;
  return map[key]||null;
}
function upgradeValue(v,upgrade){
  if(!upgrade || typeof v!=="number") return v;
  // Il miglioramento aumenta il valore base del 10% per livello.
  return v * (1 + 0.1 * upgrade);
}
function upgradeBonusValue(v,upgrade,isPercent=false){
  if(typeof v!=="number") return v;
  if(!upgrade) return Math.abs(v);
  const raw=Math.abs(v)*(1 + 0.1 * upgrade);
  // I bonus migliorati vengono arrotondati verso l'alto:
  // bonus normali a 2 decimali, bonus percentuali all'intero percentuale.
  return isPercent ? Math.ceil(raw*100) : Math.ceil(raw*100)/100;
}
function damageAtLevel(item,level,upgrade){
  if(item?.dmg_min==null || item?.dmg_max==null) return null;
  const u=upgradeValue(Number(item.dmg_min),upgrade);
  const v=upgradeValue(Number(item.dmg_max),upgrade);
  const info=perLevelInfo(item,"dmg");
  if(info && level>0 && typeof item.dmg==="number") {
    const bonus=calcBonusValue(item,"dmg",item.dmg,level,upgrade);
    return {min:u+bonus,max:v+bonus};
  }
  return {min:u,max:v};
}
function calcBonusValue(item,k,v,level,upgrade){
  const info=perLevelInfo(item,k);
  const isPercent=CONFIG.percentBonuses.has(k);
  const factor=1 + 0.1 * (upgrade||0);
  if(info){
    if(level>0){
      // Importante: il miglioramento viene applicato PRIMA dell'arrotondamento.
      // Così il valore segue: bonus × livello × miglioramento, poi roundingMethod.
      const raw=level * Math.abs(v) * factor * (isPercent ? 100 : 1);
      const method=info.roundingMethod||"ceil";
      if(method==="floatceil") return Math.ceil(raw);
      if(method==="floor") return Math.floor(raw);
      if(method==="round") return Math.round(raw);
      return Math.ceil(raw);
    }
    const value=Math.abs(v)*factor;
    if(!upgrade) return isPercent ? value*100 : value;
    return upgradeBonusValue(v,upgrade,isPercent);
  }
  return upgradeBonusValue(v,upgrade,isPercent);
}
function bonusHtml(k,v,level,upgrade,item){
  const value=calcBonusValue(item,k,v,level,upgrade);
  const suffix=perLevelInfo(item,k)&&level===0?` (${LANG.per_level})`:"";
  if(CONFIG.percentBonuses.has(k)) return `<p class="popup_txtgreen">+ ${fmt(value)}% ${CONFIG.bonusLabels[k]||k}${suffix}</p>`;
  const cls=(k==="str"||k==="mob"||k==="dex"||k==="cha")?"popup_attribute":"popup_skill";
  return `<p class="${cls}">+ ${fmt(value)} ${CONFIG.bonusLabels[k]||k}${suffix}</p>`;
}
function specialBonusHtml(k,v,item,upgrade){
  const value=upgradeBonusValue(v,upgrade,false);
  if(k.startsWith("fb")){
    const labels={fbdef:"Difesa (Bonus battaglia per il forte)",fboff:"Attacco (Bonus battaglia per il forte)",fbres:"Resistenza (Bonus battaglia per il forte)",fbdefs:"Difesa (Bonus settore battaglia per il forte)",fboffs:"Attacco (Bonus settore battaglia per il forte)",fbdmgs:"Danni (Bonus settore battaglia per il forte)"};
    return `<p class="popup_fb">+ ${fmt(value)} ${esc(labels[k]||k)}</p>`;
  }
  if(k.startsWith("lbr_")){
    const found=(item._job_bonus_desc||[]).find(x=>`lbr_${x[0]}`===k);
    const label=found?String(found[1]).replace(/^\+\s*[-+\d.,]+\s*/,''):k;
    return `<p class="popup_txtgreen">+ ${fmt(value)} ${esc(label)}</p>`;
  }
  if(k==="labor_pts") return `<p class="popup_txtgreen">+ ${fmt(value)} Punti lavoro</p>`;
  if(k==="pra") return `<p class="popup_txtgreen">+ ${fmt(value)} Pregare</p>`;
  if(k==="health_bonus") return `<p class="popup_txtgreen">+ ${fmt(value)} Punti vita</p>`;
  if(k==="revival") return `<p class="popup_txtgreen">Ripresa immediata dopo KO</p>`;
  if(k==="dmg"){const value2=calcBonusValue(item,k,v,characterLevel(),upgrade);return `<p class="popup_dmg">+ ${fmt(value2)} ${LANG.damages}${item.per_level&&item.per_level.damage?` (${LANG.per_level})`:""}</p>`;}
  return null;
}
function fixedSpecialDescriptions(item){
  const out=[];
  if(!Array.isArray(item?.bonus_desc)) return out;
  for(const raw of item.bonus_desc){
    const desc=String(raw||'');
    if(/\(\s*\(?\s*per\s*Livello\s*\)?\s*\)/i.test(desc)) continue;
    const m=desc.match(/([+-]?\d+(?:[.,]\d+)?)\s*%?/);
    if(!m) continue;
    const n=Number(m[1].replace(',','.'));
    if(!Number.isFinite(n)) continue;
    const pct=/%/.test(desc);
    let label=desc.replace(/^[+\-]?\d+(?:[.,]\d+)?\s*%?\s*/,'').trim();
    if(!label) continue;
    if(/esperienza/i.test(label)) out.push({key:'xp',value:n,pct,label});
    else if(/soldi|salario/i.test(label)) out.push({key:'money',value:n,pct,label});
    else if(/maggior\s+fortuna|\bfortuna\b/i.test(label)) out.push({key:'luck',value:n,pct,label});
    else if(/rigenerazione/i.test(label)) out.push({key:'regen',value:n,pct,label});
    else if(/probabilit(?:à|a)\s+di\s+trovare\s+prodotti/i.test(label)) out.push({key:'drop',value:n,pct,label});
    else if(/velocit(?:à|a)/i.test(label)) out.push({key:'spd',value:n,pct,label});
    else if(/punti\s+lavoro/i.test(label)) out.push({key:'labor_pts',value:n,pct:false,label});
    else if(/pregare/i.test(label)) out.push({key:'pra',value:n,pct:false,label});
  }
  return out;
}
function fixedSpecialHtml(item,upgrade){
  const rows=fixedSpecialDescriptions(item);
  if(!rows.length) return '';
  let h='';
  for(const r of rows){
    const value=upgradeBonusValue(r.value,upgrade,false);
    const suffix=r.pct?'%':'';
    h+=`<p class="popup_txtgreen">+ ${fmt(value)}${suffix} ${esc(r.label)}</p>`;
  }
  return h;
}
function createPopup(item){
  const a={...item}, level=characterLevel(), upgrade=selectedUpgrade(item), upgraded=upgrade>0;
  let s=`<div class="popup_image">`;
  if(upgraded)s+=`<div class="item_level_popup"><span>${upgrade}</span></div>`;
  s+=`<img src="${imageUrl(a)}" alt=""></div><div class="popup_divider"></div>`;
  const eventInfo=a.set&&EVENT_INFO_BY_SET[a.set]?EVENT_INFO_BY_SET[a.set]:null;s+=`<p class="popup_name">${esc(a.name)}</p>`;if(eventInfo)s+=`<p class="popup_event_line"><img src="${eventInfo.icon}" alt="">${esc(eventInfo.text)} ${esc(eventInfo.year)}</p>`;s+=`<p class="popup_type">${esc(getItalianCategoryName(a))}</p><br/>`;
  if(a.dmg_min!=null&&a.dmg_max!=null){const dd=damageAtLevel(a,level,upgrade);s+=`<p class="popup_dmg">${fmt(dd.min)}-${fmt(dd.max)} ${LANG.damages}</p>`;}
  if(Array.isArray(a.text)){for(const x of a.text)s+=`<p class="popup_text">${esc(x)}</p>`;s+="<br/>";}
  const handled=new Set(["name","type","cdn_cat","cdn_img","lvl","id","bp","sp","upg","auc","sex","text","textjob","bonus","dmg_min","dmg_max","hspd","set","craft","jobs","kshbn","bonus_desc","_job_bonus_desc","set_name"]);
  const order=["str","mob","dex","cha","con","punch","tou","sta","hea","rid","ref","dod","hid","swi","aim","sho","pit","fin","rep","lea","tac","tra","ani","app","fir","her","xp","money","luck","regen","drop","spd","pra","labor_pts","dmg","fbdef","fboff","fbres","fbdefs","fboffs","fbdmgs"];
  const keys=[...order,...Object.keys(item).filter(k=>!order.includes(k))];
  for(const k of keys){const v=item[k];if(handled.has(k)||typeof v!=="number"||(v===0&&k!=="pra"))continue;if(["xp","money","luck","regen","drop","spd","labor_pts","pra"].includes(k)&&fixedSpecialDescriptions(item).some(r=>r.key===k))continue;if(k==="dmg"&&perLevelInfo(item,"dmg")&&level>0)continue;if(!Object.prototype.hasOwnProperty.call(CONFIG.bonusLabels,k)&&!k.startsWith("lbr_")&&!k.startsWith("fb"))continue;let h=null;if(k.startsWith("fb")||k.startsWith("lbr_")||["labor_pts","pra","health_bonus","revival","dmg"].includes(k))h=specialBonusHtml(k,v,item,upgrade);else h=bonusHtml(k,v,level,upgrade,item);if(h)s+=h;}
  s+=fixedSpecialHtml(a,upgrade);
  if(Array.isArray(a.textjob)){for(const x of a.textjob)s+=`<p class="popup_txtgreen">${esc(x)}</p>`;s+="<br/>";}
  if(Array.isArray(a.bonus)){for(const x of a.bonus)s+=`<p class="popup_bonus">${esc(x)}</p>`;s+="<br/>";}
  if(Array.isArray(a.jobs)){s+=`<div style="text-align:center"><table class="popup_job">`;for(const job of a.jobs)s+=`<tr><td><img src="${CONFIG.cdn}/images/jobs/${esc(job[1])}.png"></td><td>&nbsp;&nbsp;${esc(job[0])}</td></tr>`;s+="</table></div>";}
  s+=`<div class="popup_infos">`;
  const italianSet=getItalianSetName(a);
  if(italianSet)s+=`<p class="popup_set">${esc(italianSet)}</p><br/>`;
  if(a.sp){s+=`<div class="popup_prices"><span class="popup_price"><img class="price_icon" src="${BUY_ICON}">${fmt(a.bp)} $</span><span class="popup_price"><img class="price_icon" src="${SELL_ICON}">${fmt(a.sp)} $</span></div>`;}else s+=`<i>${LANG.unsalable}</i><br/><br/>`;
  if(a.lvl)s+=`${LANG.level} <b>${a.lvl}</b><br/>`;
  s+=a.auc===1&&!upgraded?`<span class="popup_txtgreen">${LANG.auction}</span><br/>`:`<span class="popup_txtred">${LANG.not_auction}</span><br/>`;
  s+=a.upg===0?`<span class="popup_txtred">${LANG.not_upgrade}</span><br/>`:`<span class="popup_txtgreen">${LANG.upgrade}</span><br/>`;
  const shownId=upgrade?String(a.id).slice(0,-1)+upgrade:a.id;s+=`<br/><p class="popup_id">[item=<b>${esc(shownId)}</b>]</p></div>`;return s;
}
function position(ev){
  const p=$("#popup_window");
  const w=innerWidth,h=innerHeight,r=p.getBoundingClientRect();
  const x=ev.clientX+r.width+20>w?ev.clientX-r.width-20+(ev.pageX-ev.clientX):ev.clientX+20+(ev.pageX-ev.clientX);
  const y=ev.clientY+r.height+20>h?h-r.height+(ev.pageY-ev.clientY):ev.clientY+20+(ev.pageY-ev.clientY);
  p.style.top=`${Math.max(0,y)}px`;p.style.left=`${Math.max(0,x)}px`;
}
function show(item,ev){
  clearTimeout(timer);activeItem=item;lastEvent=ev;
  timer=setTimeout(()=>{
    if(activeItem!==item)return;
    $("#popup_contents").innerHTML=createPopup(item);
    const p=$("#popup_window");p.style.display="block";p.setAttribute("aria-hidden","false");position(lastEvent||ev);
  },200);
}
function hide(){clearTimeout(timer);activeItem=null;$("#popup_window").style.display="none";$("#popup_window").setAttribute("aria-hidden","true")}
function isPerLevelBonus(item,key){return !!perLevelInfo(item,key)}
function score(item,weights){
  let total=0;
  const level=characterLevel();
  for(const [k,m] of Object.entries(weights)){
    if(k==="bool"||k==="dmglvl")continue;
    const v=item[k];
    if(typeof v!=="number")continue;
    if((k==="dmg_min"||k==="dmg_max") && item.dmg_min!=null && item.dmg_max!=null){
      const dd=damageAtLevel(item,level,selectedUpgrade(item));
      total += (k==="dmg_min"?dd.min:dd.max) * m;
      continue;
    }
    const info=perLevelInfo(item,k);
    if(info){
      total += calcBonusValue(item,k,v,level,selectedUpgrade(item)) * m;
    }else{
      let value=upgradeValue(v,selectedUpgrade(item));
      if(CONFIG.percentBonuses.has(k)) value*=100;
      total += value * m;
    }
  }
  return total;
}
function init(){
  // V4: i dati sono incorporati nella pagina, quindi index.html funziona anche con doppio clic (file://).
  items=EMBEDDED_ITEMS.map(x=>({...x, set_name:getItalianSetName(x)}));
  $("#count").textContent=`${items.length} ${CATEGORY_LABEL.toLowerCase()}`;
  $("#search").addEventListener("input",render);
  $("#sort").addEventListener("change",render);
  $("#level").addEventListener("input",()=>{
    render();
    if(activeItem&&$("#popup_window").style.display==="block")$("#popup_contents").innerHTML=createPopup(activeItem);
  });
  render();
}
init();

/* =========================
   V25 UI: inline upgrade + multi-select compare
   ========================= */
function compareValue(item,key){
  const v=item[key];
  if(typeof v!=="number" || (v===0 && key!=="pra")) return null;
  if((key==="dmg_min"||key==="dmg_max") && item.dmg_min!=null && item.dmg_max!=null){
    const dd=damageAtLevel(item,characterLevel(),selectedUpgrade(item));
    return key==="dmg_min"?dd.min:dd.max;
  }
  const lvl=selectedUpgrade(item);
  if(perLevelInfo(item,key)){
    // calcBonusValue restituisce già i punti percentuali per i bonus % per-livello.
    return calcBonusValue(item,key,v,characterLevel(),lvl);
  }
  const value=upgradeValue(v,lvl);
  // Nel JSON i bonus % fissi sono frazioni: 0.002 = 0,2%.
  // Nel confronto dobbiamo portarli nella stessa scala dei bonus % per-livello.
  return CONFIG.percentBonuses.has(key) ? value*100 : value;
}
function compareLabel(item,key){
  if(CONFIG.bonusLabels[key]) return CONFIG.bonusLabels[key];
  if(key.startsWith("fb")) return ({fbdef:"Difesa (Bonus battaglia)",fboff:"Attacco (Bonus battaglia)",fbres:"Resistenza (Bonus battaglia)",fbdefs:"Difesa (Bonus settore battaglia)",fboffs:"Attacco (Bonus settore battaglia)",fbdmgs:"Danni (Bonus settore battaglia)"})[key]||key;
  if(key.startsWith("lbr_")){
    const found=(item._job_bonus_desc||[]).find(x=>`lbr_${x[0]}`===key);
    return found?String(found[1]).replace(/^\+\s*[-+\d.,]+\s*/,""):key;
  }
  return null;
}
function compareFormat(item,key,value){
  if(value==null)return "—";
  const pct=CONFIG.percentBonuses.has(key);
  const sign=value>0?"+ ":"";
  return sign+fmt(value)+(pct?"%":"");
}
function compareKeys(a,b){
  const order=["str","mob","dex","cha","con","punch","tou","sta","hea","rid","ref","dod","hid","swi","aim","sho","pit","fin","rep","lea","tac","tra","ani","app","labor_pts","pra","health_bonus","revival","dmg","fbdef","fboff","fbres","fbdefs","fboffs","fbdmgs","spd","xp","money","luck","regen","drop"];
  const all=[...order,...Object.keys(a||{}),...Object.keys(b||{})];
  return [...new Set(all)].filter(k=>compareLabel(a,k)||compareLabel(b,k)).filter(k=>compareValue(a,k)!==null||compareValue(b,k)!==null);
}
function renderCompare(){
  const panel=$("#compare_panel");
  const chosen=items.filter(i=>compareSelected.has(String(i.id)));
  if(chosen.length<2){panel.hidden=true;panel.innerHTML="";return;}
  panel.hidden=false;
  const cols=Math.min(chosen.length,MAX_COMPARE);
  let html=`<div class="compare_title">CONFRONTO · ${chosen.length} pantaloni</div>`;
  html+=`<div class="compare_multi_head" style="grid-template-columns:repeat(${cols},minmax(0,1fr))">`;
  for(const x of chosen.slice(0,MAX_COMPARE)){
    html+=`<div class="compare_card"><img src="${imageUrl(x)}" alt=""><div class="compare_name">${esc(x.name)}</div><div class="compare_lvl"><span class="icon_level"></span>${selectedUpgrade(x)}</div></div>`;
  }
  html+=`</div>`;
  const keySet=new Set();
  for(const x of chosen) for(const k of Object.keys(x)) if(compareLabel(x,k)&&compareValue(x,k)!==null) keySet.add(k);
  const order=["str","mob","dex","cha","con","punch","tou","sta","hea","rid","ref","dod","hid","swi","aim","sho","pit","fin","rep","lea","tac","tra","ani","app","labor_pts","pra","health_bonus","revival","dmg","fbdef","fboff","fbres","fbdefs","fboffs","fbdmgs","spd","xp","money","luck","regen","drop"];
  const keys=[...order,...keySet].filter((k,i,a)=>a.indexOf(k)===i && keySet.has(k));
  html+=`<table class="compare_table compare_multi"><tbody>`;
  for(const k of keys){
    const vals=chosen.slice(0,MAX_COMPARE).map(x=>compareValue(x,k));
    const nums=vals.filter(v=>v!=null);
    const max=Math.max(...nums),min=Math.min(...nums);
    html+=`<tr>`;
    for(const v of vals){
      let cls="equal";
      if(v!=null&&max!==min) cls=v===max?"better":v===min?"worse":"equal";
      html+=`<td class="val ${cls}">${compareFormat(chosen[vals.indexOf(v)]||chosen[0],k,v)}</td>`;
    }
    html+=`</tr>`;
    html+=`<tr class="compare_label_row"><td colspan="${cols}">${esc(compareLabel(chosen.find(x=>compareValue(x,k)!==null)||chosen[0],k)||k)}</td></tr>`;
  }
  html+=`</tbody></table>`;
  html+=`<div class="compare_hint">Verde = valore migliore · Rosso = valore peggiore. Il livello si modifica direttamente sull'icona del cappello.</div>`;
  panel.innerHTML=html;
}

function updateCompareBar(){
  const n=compareSelected.size;
  $("#compare_status").textContent=n===0?"Seleziona 2–4 armi per il confronto":`${n} ${n===1?"arma":"armi"} ${n===1?"selezionata":"selezionate"}`;
  $("#compare_btn").disabled=n<2;
}
function updateLevelBadge(el,item){
  const lvl=selectedUpgrade(item);
  const controls=el.querySelector(".upgrade_controls");
  if(controls){
    controls.dataset.lvl=String(lvl);
    const badge=controls.querySelector(".item_level");
    const value=controls.querySelector(".upgrade_level_value");
    if(badge){
      badge.innerHTML=`<span class="icon_level"></span>`;
    }
    if(value) value.textContent=String(lvl);
  }
  el.dataset.lvl=String(lvl);
}
function setUpgrade(item,level,el){
  level=Math.max(0,Math.min(5,Number(level)||0));
  upgradeById.set(String(item.id),level);
  updateLevelBadge(el,item);
  renderCompare();

  // Il popup deve essere il vero popup dell'oggetto, aggiornato immediatamente
  // con i valori del nuovo livello. Non dipendiamo dal fatto che il mouse
  // sia ancora considerato sopra la card dopo il click sui pulsanti +/- .
  activeItem=item;
  const popup=$("#popup_window");
  $("#popup_contents").innerHTML=createPopup(item);
  popup.style.display="block";
  popup.setAttribute("aria-hidden","false");
  if(lastEvent) position(lastEvent);

  if($("#sort").value){
    render();
    // render() ricrea le card: riagganciamo il popup alla card corrente.
    activeItem=item;
    $("#popup_contents").innerHTML=createPopup(item);
    popup.style.display="block";
    popup.setAttribute("aria-hidden","false");
    if(lastEvent) position(lastEvent);
  }
}
function makeUpgradeButton(cls,title,item,el,delta){
  const b=document.createElement("span");
  b.className=cls;b.title=title; b.setAttribute("role","button"); b.tabIndex=0;
  // Passando sui +/- mostriamo sempre il popup dell'oggetto, già al livello corrente.
  b.addEventListener("mouseenter",e=>{
    e.stopPropagation();
    lastEvent=e;
    activeItem=item;
    $("#popup_contents").innerHTML=createPopup(item);
    const p=$("#popup_window");
    p.style.display="block";
    p.setAttribute("aria-hidden","false");
    position(e);
  });
  const act=e=>{
    e.preventDefault();
    e.stopPropagation();
    setUpgrade(item,selectedUpgrade(item)+delta,el);
  };
  b.addEventListener("mousedown",e=>e.stopPropagation());
  b.addEventListener("click",act);
  b.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" ")act(e)});
  return b;
}
function makeCompareCheck(item,el){
  const c=document.createElement("input");
  c.type="checkbox";c.className="compare_check";c.title="Seleziona per il confronto";
  c.checked=compareSelected.has(String(item.id));
  c.addEventListener("mousedown",e=>e.stopPropagation());
  c.addEventListener("click",e=>e.stopPropagation());
  c.addEventListener("change",e=>{
    const id=String(item.id);
    if(e.target.checked){
      if(compareSelected.size>=MAX_COMPARE){e.target.checked=false;return;}
      compareSelected.add(id);el.classList.add("compare_selected");
    }else{compareSelected.delete(id);el.classList.remove("compare_selected");}
    updateCompareBar();renderCompare();
  });
  return c;
}
function render(){
  const q=$("#search").value.trim().toLowerCase();
  let list=items.filter(i=>!q||JSON.stringify(i).toLowerCase().includes(q));
  const selected=$("#sort").value;
  if(selected){const weights=JSON.parse(selected);list.sort((a,b)=>score(b,weights)-score(a,weights));}
  const c=$("#items");c.innerHTML="";
  for(const item of list){
    const el=document.createElement("div");
    el.className="item_container"+(compareSelected.has(String(item.id))?" compare_selected":"");
    el.dataset.popup=JSON.stringify(item);el.dataset.lvl=String(selectedUpgrade(item));
    const img=new Image();img.src=imageUrl(item);img.alt=item.name;img.loading="lazy";
    img.onerror=()=>{img.style.display="none";el.insertAdjacentHTML("beforeend",`<div class="item_missing" title="Immagine non disponibile dal CDN"><div class="fallback_hat">🎩</div><span>${esc(item.name)}</span></div>`)};
    el.appendChild(img);
    if(item.upg===1){
      // V34: il badge del miglioramento resta visibile sui cappelli già migliorati.
      // I controlli +/- compaiono solo passando il mouse, nell'ordine:
      // icona + numero, +, numero, -. Al livello 0 resta visibile solo il + in hover.
      const controls=document.createElement("span");
      controls.className="upgrade_controls";
      controls.dataset.lvl=String(selectedUpgrade(item));

      const badge=document.createElement("span");
      badge.className="item_level";
      badge.innerHTML=`<span class="icon_level"></span>`;
      controls.appendChild(badge);
      controls.appendChild(makeUpgradeButton("upgrade","Migliora di 1 livello",item,el,1));
      const levelSpan=document.createElement("span");
      levelSpan.className="upgrade_level_value level";
      levelSpan.textContent=String(selectedUpgrade(item));
      controls.appendChild(levelSpan);
      controls.appendChild(makeUpgradeButton("downgrade","Riduci di 1 livello",item,el,-1));
      el.appendChild(controls);
    }
    el.appendChild(makeCompareCheck(item,el));
    el.addEventListener("mouseenter",e=>show(item,e));
    el.addEventListener("mousemove",e=>{lastEvent=e;if($("#popup_window").style.display==="block")position(e)});
    el.addEventListener("mouseleave",hide);
    c.appendChild(el);
  }
  updateCompareBar();renderCompare();
}

// V25 init: direct controls, no M0/M1... selectors.
(function wireV25(){
  const compareBtn=$("#compare_btn"),clearBtn=$("#compare_clear");
  if(compareBtn)compareBtn.addEventListener("click",()=>{renderCompare();$("#compare_panel").scrollIntoView({behavior:"smooth",block:"nearest"})});
  if(clearBtn)clearBtn.addEventListener("click",()=>{compareSelected.clear();render()});
})();
